// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  ArchiveRestoreIcon,
  CheckCircle2Icon,
  CheckIcon,
  CodeIcon,
  FileCode2Icon,
  GlobeIcon,
  LibraryIcon,
  PlusIcon,
  RotateCwIcon,
  SearchIcon,
  SettingsIcon,
  SparklesIcon,
  TerminalIcon,
  type LucideIcon,
} from 'lucide-react'
import type { ReactNode } from 'react'

import { BrowserChrome, DemoStage, type Build } from '@/app/demos/stage'

import {
  AFTER_PAUSE,
  AFTER_RELOAD,
  BEFORE_RELOAD,
  CAPTIONS,
  CATEGORIES,
  GALLERY,
  HOST,
  MATCHES,
  PAGE_URL,
  PAUSE_NEEDS_RELOAD,
  PICK,
  QUERY,
  RAN_LINE,
  STATE_LABEL,
} from './script'

const PANEL = 252
const TABS: { id: string; label?: string; icon: LucideIcon }[] = [
  { id: 'page', label: 'This page', icon: GlobeIcon },
  { id: 'library', label: 'Library', icon: LibraryIcon },
  { id: 'gallery', label: 'Gallery', icon: SparklesIcon },
  { id: 'editor', icon: FileCode2Icon },
  { id: 'settings', icon: SettingsIcon },
  { id: 'backup', icon: ArchiveRestoreIcon },
]
const SHOWN = GALLERY.slice(0, 3)
const ON = { backgroundColor: '#10b981' }
const OFF = { backgroundColor: 'var(--demo-tint-18)' }

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const selectTab = (id: string) => {
    tl.to(
      qa('tab'),
      { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)', duration: 0.15 },
      '<',
    )
    tl.to(
      q(`tab-${id}`),
      { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)', duration: 0.15 },
      '<',
    )
  }

  step(0)
  move('search', { at: 0.4, ax: 0.3 })
  click('search')
  tl.to(q('search-ph'), { opacity: 0, duration: 0.1 }, '<')
  type('search-text', QUERY, { speed: 0.07 })
  tl.to(qa('card-other'), { opacity: 0, duration: 0.2 }, '<0.3')
  tl.fromTo(
    q('card-pick'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.25, immediateRender: false },
    '>',
  )
  move('add', { at: '+=0.2' })
  click('add')
  tl.to(q('add'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('added'), { opacity: 1, duration: 0.15 }, '<')
  tl.set(q('counts'), { text: '1/1 active' }, '<')
  tl.fromTo(
    q('lib-count'),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, immediateRender: false },
    '<',
  )

  step(1, '+=0.4')
  move('tab-page')
  click('tab-page')
  selectTab('page')
  tl.to(q('gallery'), { opacity: 0, duration: 0.15 }, '<')
  tl.fromTo(
    q('this-page'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.25, immediateRender: false },
    '>',
  )
  move('reload', { at: '+=0.3' })
  click('reload')
  tl.to(q('reload'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('page-body'), { opacity: 0.2, duration: 0.15 }, '<')
  tl.to(q('container'), { width: '100%', duration: 0.01 }, '>')
  tl.to(q('page-body'), { opacity: 1, duration: 0.3 }, '>')
  tl.to(q('summary-none'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('summary-ran'), { opacity: 1, duration: 0.15 }, '<')
  tl.to(q('bar'), { backgroundColor: '#10b981', duration: 0.3 }, '<')
  tl.to(q('chip-reload'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('chip-ran'), { opacity: 1, duration: 0.15 }, '<')
  tl.to(q('icon-reload'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('icon-ran'), { opacity: 1, duration: 0.15 }, '<')
  tl.to(q('line-reload'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('line-ran'), { opacity: 1, duration: 0.15 }, '<')
  tl.fromTo(
    q('ran-here'),
    { opacity: 0, scale: 0.6 },
    { opacity: 1, scale: 1, duration: 0.3, immediateRender: false },
    '<',
  )
  wait(0.7)

  step(2, '+=0.1')
  move('global', { ax: 0.3 })
  click('global')
  tl.to(q('global'), { ...OFF, duration: 0.2 }, '<')
  tl.to(q('global-knob'), { x: 0, duration: 0.2 }, '<')
  tl.set(q('global-label'), { text: 'Scripts off' }, '<')
  tl.to(q('pill-ready'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('pill-paused'), { opacity: 1, duration: 0.15 }, '<')
  tl.fromTo(
    q('paused-hint'),
    { opacity: 0, height: 0 },
    { opacity: 1, height: 'auto', duration: 0.3, immediateRender: false },
    '<',
  )
  if (PAUSE_NEEDS_RELOAD) {
    tl.to(q('stops'), { opacity: 1, duration: 0.2 }, '<0.2')
    tl.to(q('reload'), { opacity: 1, duration: 0.2 }, '<')
  }
  move('row', { at: '+=0.3', ax: 0.4 })
  cursorOut('+=0.8')
  final('+=0.1')
  wait(1.4)

  tl.set(
    [
      q('this-page'),
      q('card-pick'),
      q('added'),
      q('lib-count'),
      q('summary-ran'),
      q('chip-ran'),
      q('icon-ran'),
      q('line-ran'),
      q('ran-here'),
      q('pill-paused'),
      q('stops'),
    ],
    { opacity: 0 },
    0,
  )
  tl.set(
    [
      q('gallery'),
      q('search-ph'),
      q('add'),
      q('summary-none'),
      q('chip-reload'),
      q('icon-reload'),
      q('line-reload'),
      q('reload'),
      q('pill-ready'),
    ],
    { opacity: 1 },
    0,
  )
  tl.set(qa('card-other'), { opacity: 1 }, 0)
  tl.set(q('paused-hint'), { opacity: 0, height: 0 }, 0)
  tl.set(q('counts'), { text: '0/0 active' }, 0)
  tl.set(q('global'), { ...ON }, 0)
  tl.set(q('global-knob'), { x: 10 }, 0)
  tl.set(q('global-label'), { text: 'Scripts on' }, 0)
  tl.set(q('bar'), { backgroundColor: '#f59e0b' }, 0)
  tl.set(q('container'), { width: '64%' }, 0)
  tl.set(qa('tab'), { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)' }, 0)
  tl.set(q('tab-gallery'), { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)' }, 0)
}

function Stack({ children, className }: { children: ReactNode; className?: string }) {
  return <span className={`grid [&>*]:[grid-area:1/1] ${className ?? ''}`}>{children}</span>
}

function GalleryCard({ script, dataD }: { script: (typeof GALLERY)[number]; dataD: string }) {
  return (
    <div data-d={dataD} className="rounded-lg border border-line bg-ink/[0.02] p-1.5">
      <div className="flex items-start gap-1.5">
        <span className="flex size-5 shrink-0 items-center justify-center rounded-md bg-[color-mix(in_srgb,var(--accent)_14%,transparent)] text-[var(--accent)]">
          {script.category === 'developer' ? (
            <TerminalIcon className="size-3" />
          ) : (
            <SparklesIcon className="size-3" />
          )}
        </span>
        <span className="min-w-0">
          <span className="block truncate text-[8.5px] font-semibold text-ink">{script.name}</span>
          <span className="block truncate text-[7px] text-muted">{script.sites}</span>
        </span>
      </div>
      <p className="mt-1 line-clamp-2 text-[7.5px] leading-[10px] text-muted">
        {script.description}
      </p>
      <div className="mt-1 flex items-center justify-end gap-1 text-[7.5px]">
        <span className="flex items-center gap-0.5 px-1 text-ink-soft">
          <CodeIcon className="size-2.5" /> Code
        </span>
        {script.id === PICK.id ? (
          <Stack>
            <span
              data-d="add"
              className="flex items-center gap-0.5 rounded bg-[var(--accent)] px-1.5 py-0.5 font-semibold text-canvas"
            >
              <PlusIcon className="size-2.5" /> Add
            </span>
            <span
              data-d="added"
              className="flex items-center gap-0.5 rounded border border-line-strong px-1.5 py-0.5 text-ink opacity-0"
            >
              <CheckIcon className="size-2.5 text-emerald-400" /> Added
            </span>
          </Stack>
        ) : (
          <span className="flex items-center gap-0.5 rounded bg-[var(--accent)] px-1.5 py-0.5 font-semibold text-canvas">
            <PlusIcon className="size-2.5" /> Add
          </span>
        )}
      </div>
    </div>
  )
}

function Gallery() {
  return (
    <div data-d="gallery" className="absolute inset-0 flex flex-col gap-1.5">
      <span
        data-d="search"
        className="relative flex h-5 items-center gap-1 rounded-md border border-line-strong px-1.5 text-[8px]"
      >
        <SearchIcon className="size-2.5 text-muted" />
        <span data-d="search-ph" className="absolute left-5 text-muted">
          Search 30+ ready-made scripts
        </span>
        <span data-d="search-text" className="text-ink" />
      </span>
      <div className="flex gap-1 overflow-hidden">
        {['All', ...CATEGORIES.map((category) => category.label)].map((label, index) => (
          <span
            key={label}
            className={`shrink-0 rounded-full border px-1.5 py-px text-[7px] ${index === 0 ? 'border-transparent bg-[var(--accent)] text-canvas' : 'border-line text-muted'}`}
          >
            {label}
          </span>
        ))}
      </div>
      <div className="relative">
        <div className="space-y-1">
          {SHOWN.map((script) => (
            <GalleryCard key={script.id} script={script} dataD="card-other" />
          ))}
        </div>
        <div className="absolute inset-x-0 top-0">
          {MATCHES.map((script) => (
            <GalleryCard key={script.id} script={script} dataD="card-pick" />
          ))}
        </div>
      </div>
    </div>
  )
}

function ThisPage() {
  return (
    <div data-d="this-page" className="absolute inset-0 flex flex-col gap-1.5 opacity-0">
      <section className="rounded-lg border border-line p-1.5">
        <div className="flex items-start gap-1.5">
          <span className="min-w-0 flex-1">
            <span className="block text-[7.5px] text-muted">Scripts for {HOST}</span>
            <Stack className="text-[9.5px] font-semibold text-ink">
              <span data-d="summary-none">Nothing has run on this page yet</span>
              <span data-d="summary-ran" className="opacity-0">
                1 of 1 ran on this page
              </span>
            </Stack>
          </span>
          <span
            data-d="reload"
            className="flex h-5 shrink-0 items-center gap-1 rounded border border-line-strong px-1.5 text-[7.5px] text-ink"
          >
            <RotateCwIcon className="size-2.5" /> Reload page
          </span>
        </div>
        <span
          data-d="bar"
          className="mt-1.5 block h-1 rounded-full"
          style={{ backgroundColor: '#f59e0b' }}
        />
        <Stack className="mt-1.5 text-[7.5px] font-medium">
          <span
            data-d="chip-reload"
            className="flex w-fit items-center gap-1 rounded-full bg-amber-500/10 px-1.5 py-0.5 text-amber-400"
          >
            <RotateCwIcon className="size-2.5" /> {STATE_LABEL[BEFORE_RELOAD]} 1
          </span>
          <span
            data-d="chip-ran"
            className="flex w-fit items-center gap-1 rounded-full bg-emerald-500/10 px-1.5 py-0.5 text-emerald-400 opacity-0"
          >
            <CheckCircle2Icon className="size-2.5" /> {STATE_LABEL[AFTER_RELOAD]} 1
          </span>
        </Stack>
      </section>
      <div data-d="row" className="flex items-center gap-1.5 rounded-lg border border-line p-1.5">
        <Stack>
          <span
            data-d="icon-reload"
            className="flex size-6 items-center justify-center rounded-full bg-amber-500/10 text-amber-400"
          >
            <RotateCwIcon className="size-3" />
          </span>
          <span
            data-d="icon-ran"
            className="flex size-6 items-center justify-center rounded-full bg-emerald-500/10 text-emerald-400 opacity-0"
          >
            <CheckCircle2Icon className="size-3" />
          </span>
        </Stack>
        <span className="min-w-0 flex-1">
          <span className="block truncate text-[8.5px] font-medium text-ink">{PICK.name}</span>
          <Stack className="text-[7.5px] text-muted">
            <span data-d="line-reload">Reload the page to run it</span>
            <span data-d="line-ran" className="opacity-0">
              {RAN_LINE}
              <span data-d="stops" className="opacity-0">
                {' '}
                · Stops after reload
              </span>
            </span>
          </Stack>
        </span>
        <span className="flex h-3 w-5 items-center rounded-full bg-emerald-500 px-0.5">
          <span className="size-2 translate-x-2 rounded-full bg-white" />
        </span>
      </div>
      <div className="rounded-lg border border-line p-1.5">
        <p className="text-[8px] font-semibold text-ink">Find scripts for this site</p>
        <p className="mt-1 flex gap-1 text-[7px] text-ink-soft">
          {['Greasy Fork', 'OpenUserJS', 'userscript.zone'].map((label) => (
            <span key={label} className="rounded border border-line px-1 py-0.5">
              {label} ↗
            </span>
          ))}
        </p>
      </div>
      <span className="sr-only">
        After pausing, the script still shows as {STATE_LABEL[AFTER_PAUSE]}.
      </span>
    </div>
  )
}

function Panel() {
  return (
    <div className="flex h-full flex-col gap-1.5 p-2" style={{ width: PANEL }}>
      <div className="rounded-lg border border-line px-1.5 py-1">
        <div className="flex items-center gap-1 whitespace-nowrap">
          <span
            data-d="global"
            className="flex h-3 w-5 shrink-0 items-center rounded-full px-0.5"
            style={ON}
          >
            <span
              data-d="global-knob"
              className="size-2 rounded-full bg-white"
              style={{ transform: 'translateX(10px)' }}
            />
          </span>
          <span data-d="global-label" className="text-[8px] font-medium text-ink">
            Scripts on
          </span>
          <Stack className="text-[7.5px] font-medium">
            <span
              data-d="pill-ready"
              className="flex items-center gap-1 rounded-full bg-emerald-500/10 px-1.5 py-px text-emerald-400"
            >
              <span className="size-1 rounded-full bg-emerald-500" /> Ready
            </span>
            <span
              data-d="pill-paused"
              className="flex items-center gap-1 rounded-full bg-ink/[0.06] px-1.5 py-px text-muted opacity-0"
            >
              <span className="size-1 rounded-full bg-muted" /> Paused
            </span>
          </Stack>
          <span data-d="counts" className="text-[7.5px] tabular-nums text-muted">
            0/0 active
          </span>
          <span
            data-d="ran-here"
            className="flex items-center gap-0.5 rounded-full bg-emerald-500/10 px-1 py-px text-[7px] text-emerald-400 opacity-0"
          >
            <CheckCircle2Icon className="size-2" /> 1 ran here
          </span>
          <span className="ml-auto flex items-center gap-0.5 rounded bg-[var(--accent)] px-1 py-0.5 text-[7px] font-semibold text-canvas">
            <PlusIcon className="size-2.5" />
            <span className="sr-only">New script</span>
          </span>
        </div>
        <p
          data-d="paused-hint"
          className="h-0 overflow-hidden text-[7px] leading-[10px] text-muted opacity-0"
        >
          <span className="block pt-1">
            No scripts will run on new page loads. Reload tabs that are already open to stop scripts
            running there.
          </span>
        </p>
      </div>
      <div className="flex gap-0.5 rounded-md bg-ink/[0.04] p-0.5">
        {TABS.map((tab) => {
          const Icon = tab.icon
          return (
            <span
              key={tab.id}
              data-d={`tab tab-${tab.id}`}
              className="relative flex items-center gap-0.5 whitespace-nowrap rounded px-1 py-0.5 text-[7px]"
              style={
                tab.id === 'gallery'
                  ? { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)' }
                  : { color: 'var(--demo-muted)' }
              }
            >
              <Icon className="size-2.5" />
              {tab.label}
              {tab.id === 'library' ? (
                <span
                  data-d="lib-count"
                  className="rounded-full bg-ink/10 px-1 text-[6.5px] opacity-0"
                >
                  1
                </span>
              ) : null}
            </span>
          )
        })}
      </div>
      <div className="relative min-h-0 flex-1">
        <Gallery />
        <ThisPage />
      </div>
    </div>
  )
}

function Page() {
  return (
    <div className="h-full bg-[#0d1117] text-[#c9d1d9]">
      <div className="flex h-7 items-center gap-2 border-b border-ink/10 bg-[#010409] px-3 text-[8px]">
        <span className="size-3.5 rounded-full bg-ink/80" />
        <span className="text-white/80">northwind / trail-api</span>
      </div>
      <div data-d="page-body" className="h-[calc(100%-28px)] px-3 pt-2">
        <div data-d="container" className="mx-auto" style={{ width: '64%' }}>
          <p className="truncate text-[8px] text-[#8b949e]">trail-api / src / routes / orders.ts</p>
          <div className="mt-1.5 overflow-hidden rounded-md border border-ink/10">
            <div className="h-5 border-b border-ink/10 bg-[#161b22]" />
            <div className="space-y-[5px] p-2 font-mono text-[7px]">
              {[78, 92, 64, 88, 96, 52, 84, 70, 90, 60, 82, 74].map((width, line) => (
                <span key={line} className="flex items-center gap-2">
                  <span className="w-3 text-right text-[#6e7681]">{line + 1}</span>
                  <span
                    className="block h-[3px] rounded-full"
                    style={{
                      width: `${width}%`,
                      background: line % 4 === 0 ? '#d2a8ff66' : '#79c0ff44',
                    }}
                  />
                </span>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Script Studio adding ${PICK.name} from a gallery of ${GALLERY.length} scripts, reloading ${HOST} so it runs, then pausing all scripts`}
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome url={PAGE_URL} panelWidth={PANEL} panel={<Panel />}>
        <Page />
      </BrowserChrome>
    </DemoStage>
  )
}
